using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Polynomials;

internal sealed class MatchingPartitionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/Polynomials/MatchingPartition.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact matching-count fibers and complementary coefficient domination for finite unweighted simple graphs, with no bound on the vertex order.",
        H("Matching counts relative to a maximum matching"),
        Blocks(
            Paragraph(Text("Problem 4.7 of Ball–Galvin–Hyry–Weingartner, arXiv:1901.06579v2, PDF page 17, asks for all weak sorting permutations of m(1),…,m(n) for graphs of matching number n, and their growth. The results here are necessary structural prerequisites. They supply neither a graph realizing each admitted order nor an enumeration of the actual realizable class. Ties remain in scope, and m(0) is excluded from the source permutations.")),
            Node("outside", "outsideMatchings", "Outside matchings", "For finite edge sets E and Q on a finite vertex carrier, enumerate all pairwise vertex-disjoint subsets F of E minus Q, including the empty set.", DescribeRole.Definition),
            Node("untouched", "untouched", "Untouched matching edges", "For finite edge sets Q and F, retain precisely the q in Q sharing no vertex with any edge of F.", DescribeRole.Definition),
            Node("fiber", "matching_fiber_card", "Exact fiber cardinality", "Let Q be a matching contained in E, let F be an outside matching, and let k be any natural number. Matchings M contained in E with cardinality k and M minus Q equal to F are counted by choose(card(untouched Q F),k−card F) if card F is at most k, and by zero otherwise. The bijection sends a subset A of untouched Q-edges to F union A; its inverse is M intersection Q. No maximality assumption is used.", DescribeRole.Theorem),
            Node("partition", "count_partition", "Partition of every coefficient", "For every finite edge set E, every matching Q contained in E, and every k, cnt(E,k) is the sum of the guarded fiber cardinalities over all outside matchings F. Partitioning by M minus Q is exhaustive and unique.", DescribeRole.Theorem),
            Node("native-partition", "matchingCount_partition", "Original graph-count identity", "For every natural vertex order N, simple graph G on Fin N, edge-decision instance, matching Q in G and natural k, the original matchingCount G k equals the same sum with E equal to G.edgeFinset. This consumes the original owner's matchingCount_eq_cnt bridge; vertex order N and matching size are separate parameters.", DescribeRole.Theorem),
            Node("bounds", "maximum_outside_bounds", "Maximum-matching touch bounds", "For every such G and matching Q with matchingNumber G equal to card Q, and every outside matching F, put t=card F and s=card Q−card(untouched Q F). Then t is at most s, and s is at most min(2t,card Q). The lower bound adjoins every untouched Q-edge to F. The upper bound injects touched Q-edges into the at most 2t vertices of F. All relations refer to this same graph and matching.", DescribeRole.Theorem),
            Node("complement", "matchingCount_complement_le", "Complementary matching-count comparison", "For every natural N, unweighted simple graph G on Fin N and natural k with 2k at most matchingNumber G, matchingCount G k is at most matchingCount G (matchingNumber G−k). A maximum matching exists by the native count definition. Each exact fiber contributes a nonnegative complementary difference, by binomial symmetry and monotonicity. The theorem includes zero and the middle coefficient.", DescribeRole.Theorem),
            Node("rigidity", "matchingCount_rigidity", "Uniform positive complementary gap", "For every natural N and unweighted simple graph G on Fin N, put n=matchingNumber G and assume n is at least three. Either m(k)=m(n−k) for every k from zero through n, or, simultaneously for every k with 1≤k and 2k<n, the integer d=choose(n−3,k−1)−b is positive and m(k)+d≤m(n−k), where b=choose(n−3,k−2) when k≥2 and b=0 otherwise. The zero guard is essential at k=1. The proof shows that any defect has a one-edge witness touching one Q-edge or a two-edge witness touching two or three Q-edges. If every singleton and disjoint pair is balanced, the touched-edge sets are disjoint and all fibers are palindromic. Each possible small defect contributes at least d; every other fiber contributes a nonnegative gap. This is a universal graph theorem. The attaining family is supplied by sharp_gap_attained.", DescribeRole.Theorem),
            Node("attainment", "sharp_gap_attained", "One graph attains all gaps", "For every natural r, there exists an unweighted simple graph G on Fin(2(r+3)) with matchingNumber G=r+3, such that for every k with 1≤k and 2k<r+3, m(r+3−k)=m(k)+choose(r,k−1)−b, where b=choose(r,k−2) if k≥2 and b=0 otherwise. This single graph simultaneously attains all the bounds. It has matching edges joining 2i to 2i+1 for i<r+3 and the additional edges {1,2} and {3,4}; hence it is P6 together with r independent edges. Its outside matchings are exactly the empty set, either added edge, and their pair. The resulting coefficient formula is choose(r+3,k)+2 choose(r+1,k−1)+choose(r,k−2), with out-of-range terms zero. The original matchingCount and matchingNumber are used throughout; no graph-order cutoff is assumed for the universal bound.", DescribeRole.Theorem),
            Paragraph(Text("The exact source Problem 4.7 was reread in the fixed-version text. Repository and pinned Mathlib searches found the native count bridge and binomial suppliers, but no matching partition or sharp rigidity theorem in the searched scope. Crossref metadata identifies Farrell's 1992 paper On the theory of matching equivalent graphs and rook equivalent chessboards, DOI 10.1016/0016-0032(92)90095-X. Its primary text and the Kennedy primary text have not been verified here. No novelty or priority claim is made.")),
            Paragraph(Text("The four-slot escape audit remains unfinished under issue #31461. The dependent-family enrollment requires complete reconstruction of the varying graph, matching and count telescope, an exact readout bridge, whole-family variation and sensitivity, and actual observational dependence for all seven public theorems, including sharp_gap_attained. Those audit data are not supplied by the combinatorial proof. No declared_validated registration is claimed."))),
        []));

    private static DocumentBlock Node(string id, string declaration, string title, string prose,
        DescribeRole role) => Describe.Lean(
            DescribeId.Create("matching-partition-" + id), DeclarationHandle.Create(Prefix + declaration),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(prose))), role);
}
